def build_payload(model, messages, temperature=0.7, max_tokens=800, stream=False):
    if not isinstance(messages, list) or not messages:
        raise ValueError('messages 不能为空')
    if not isinstance(temperature, (int, float)) or isinstance(temperature, bool):
        raise ValueError('temperature 必须在 0~2 之间')
    if not 0 <= temperature <= 2:
        raise ValueError('temperature 必须在 0~2 之间')
    if not isinstance(max_tokens, int) or isinstance(max_tokens, bool) or max_tokens <= 0:
        raise ValueError('max_tokens 必须是正整数')
    return {
        'model': model,
        'messages': messages,
        'temperature': temperature,
        'max_tokens': max_tokens,
        'stream': bool(stream),
    }


def parse_response(data):
    if not isinstance(data, dict):
        return {'ok': False, 'error': '响应结构异常'}
    choices = data.get('choices')
    if not isinstance(choices, list) or not choices:
        return {'ok': False, 'error': '响应结构异常'}
    message = choices[0].get('message') or {}
    usage = data.get('usage') or {}
    return {
        'ok': True,
        'content': message.get('content', ''),
        'model': data.get('model', ''),
        'tokens': usage.get('total_tokens', 0),
    }


def describe_error(status, body=''):
    mapping = {
        401: 'API Key 不正确或已失效',
        403: '没有权限或账号欠费',
        404: '模型名称或接口地址不对',
        429: '请求太频繁或额度用尽，请稍后重试',
    }
    if status in mapping:
        return mapping[status]
    if isinstance(status, int) and 500 <= status < 600:
        return '服务端异常，请稍后重试'
    return f'请求失败（HTTP {status}）：{str(body)[:80]}'


msgs = [{'role': 'user', 'content': '你好'}]
print(build_payload('deepseek-chat', msgs))
print(parse_response({'model': 'deepseek-chat', 'choices': [{'message': {'content': '你好！'}}], 'usage': {'total_tokens': 12}}))
print(parse_response({'choices': []}))
for code in (401, 403, 404, 429, 502, 418):
    print(code, describe_error(code, 'some body text'))
